package builtin

// uiGrammar is the keys of ui.toml, the words of a source plugin's views,
// facets, situations and menu bar sections, by the ids its manifest's
// [source.ui] and [[source.situations]] declare.
var uiGrammar = []Key{
	{Path: "views", In: SurfaceUI, Kind: KindTable, Doc: "The words of the plugin's views, by view id."},
	{Path: "views.*", In: SurfaceUI, Kind: KindTable, Doc: "One view's words."},
	{Path: "views.*.label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The view's name, as navigation lists it. Required."},
	{Path: "views.*.unit", In: SurfaceUI, Kind: KindText, Doc: "What one of the view's rows is, such as \"Pull request\", the unit column's heading; empty for a view whose rows mix kinds."},
	{Path: "views.*.search", In: SurfaceUI, Kind: KindTable, Doc: "A custom view's search: the queries it runs at a press, the terms it toggles and the orders it offers."},
	{Path: "views.*.search.default_sort", In: SurfaceUI, Kind: KindText, Doc: "The order a query with none is read in."},
	{Path: "views.*.search.presets[]", In: SurfaceUI, Kind: KindTable, Doc: "A query run at a press."},
	{Path: "views.*.search.presets[].query", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The query, in the source's search syntax. Required."},
	{Path: "views.*.search.presets[].label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "Its words. Required."},
	{Path: "views.*.search.filters[]", In: SurfaceUI, Kind: KindTable, Doc: "A term the query toggles, or a window of recent activity."},
	{Path: "views.*.search.filters[].term", In: SurfaceUI, Kind: KindText, Doc: "The term toggled in the query."},
	{Path: "views.*.search.filters[].window", In: SurfaceUI, Kind: KindInt, Doc: "Days of recent activity the filter keeps, in place of a term."},
	{Path: "views.*.search.filters[].label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "Its words. Required."},
	{Path: "views.*.search.sorts[]", In: SurfaceUI, Kind: KindTable, Doc: "An order the search offers."},
	{Path: "views.*.search.sorts[].sort", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The order's value in the query. Required."},
	{Path: "views.*.search.sorts[].label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "Its words on its button. Required."},
	{Path: "views.*.search.sorts[].shown", In: SurfaceUI, Kind: KindText, Doc: "How a result names the order, such as \"waiting longest\"."},
	{Path: "views.*.search.decisions", In: SurfaceUI, Kind: KindTable, Doc: "How a result's decision reads, by value."},
	{Path: "views.*.search.decisions.*", In: SurfaceUI, Kind: KindText, Doc: "One decision's words."},
	{Path: "views.*.search.no_decision", In: SurfaceUI, Kind: KindText, Doc: "What a result with no decision reads."},
	{Path: "facets", In: SurfaceUI, Kind: KindTable, Doc: "The words of the plugin's facets, by facet id."},
	{Path: "facets.*", In: SurfaceUI, Kind: KindTable, Doc: "One facet's words."},
	{Path: "facets.*.label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The facet's name, as the filter menu and the groups show it. Required."},
	{Path: "facets.*.empty", In: SurfaceUI, Kind: KindText, Doc: "What a row with no value shows."},
	{Path: "facets.*.values", In: SurfaceUI, Kind: KindTable, Doc: "How each value shows, by value; a value it does not name shows as itself."},
	{Path: "facets.*.values.*", In: SurfaceUI, Kind: KindText, Doc: "One value's text."},
	{Path: "facets.*.buckets", In: SurfaceUI, Kind: KindTable, Doc: "How each age bucket of a time facet shows, by bucket id."},
	{Path: "facets.*.buckets.*", In: SurfaceUI, Kind: KindText, Doc: "One bucket's text."},
	{Path: "situations", In: SurfaceUI, Kind: KindTable, Doc: "How each situation the plugin derives shows, by kind, in a few words."},
	{Path: "situations.*", In: SurfaceUI, Kind: KindText, Doc: "One situation's words."},
	{Path: "events", In: SurfaceUI, Kind: KindTable, Doc: "How each event kind the plugin declares shows on a timeline, by kind."},
	{Path: "events.*", In: SurfaceUI, Kind: KindTable, Doc: "One event kind's words."},
	{Path: "events.*.label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The event in a few words. Required."},
	{Path: "events.*.loop", In: SurfaceUI, Kind: KindBool, Doc: "The event is the loop's doing, which the activity's loop filter keeps."},
	{Path: "events.*.data", In: SurfaceUI, Kind: KindEnum, Values: func() []Value {
		return []Value{{Name: "", Doc: "Its data as it is."}, {Name: "none", Doc: "No data."}, {Name: "first_field", Doc: "Its data up to the first colon."},
			{Name: "short_sha", Doc: "The first seven characters of a commit id."}, {Name: "requested", Doc: "Whom it asks or stops asking: shown as from that person or team, not as data."}}
	}, Doc: "How the event's data shows on a timeline."},
	{Path: "detail", In: SurfaceUI, Kind: KindTable, Doc: "How a field of the plugin's unit detail shows, by field."},
	{Path: "detail.*", In: SurfaceUI, Kind: KindTable, Doc: "One field's words."},
	{Path: "detail.*.label", In: SurfaceUI, Kind: KindText, Required: true, Doc: "The field's name. Required."},
	{Path: "detail.*.title", In: SurfaceUI, Kind: KindText, Doc: "What the field means, as its tooltip shows it."},
	{Path: "menubar", In: SurfaceUI, Kind: KindTable, Doc: "The heading of each menu bar section, by section id."},
	{Path: "menubar.*", In: SurfaceUI, Kind: KindText, Doc: "One section's heading."},
}
